<?php
/**
 * Plugin Name: Maarksho CRM & Data Bridge
 * Description: محصولات، تنوع‌ها، موجودی، سفارش، مقاله، برگه و متادیتای Rank Math/Yoast؛ ارسال صفحه‌بندی‌شده به مرکز داده مارکشو.
 * Version: 5.0.0
 * Requires PHP: 8.0
 * Author: Maarksho
 * License: GPL-2.0-or-later
 */
if(!defined('ABSPATH'))exit;
class Maarksho_Data_Bridge {
    const OPTION='maarksho_bridge_v5';
    public static function settings(){return get_option(self::OPTION,[]);}
    public static function boot(){add_action('init',[self::class,'activate']);add_action('admin_menu',[self::class,'menu']);add_action('rest_api_init',[self::class,'routes']);add_action('maarksho_bridge_tick',[self::class,'tick']);add_filter('cron_schedules',static function($s){$s['maarksho_5min']=['interval'=>300,'display'=>'Maarksho every 5 minutes'];return $s;});}
    public static function activate(){if(!wp_next_scheduled('maarksho_bridge_tick'))wp_schedule_event(time()+60,'maarksho_5min','maarksho_bridge_tick');}
    public static function deactivate(){wp_clear_scheduled_hook('maarksho_bridge_tick');}
    public static function menu(){add_menu_page('اتصال مارکشو','مارکشو','manage_options','maarksho-bridge',[self::class,'page'],'dashicons-database-export');}
    public static function page(){if(!current_user_can('manage_options'))return;$s=self::settings();$message='';
        if($_SERVER['REQUEST_METHOD']==='POST'){check_admin_referer('maarksho_bridge_save');if(isset($_POST['run'])){self::tick();$message='یک بسته پردازش شد؛ نتیجه و ادامه در وضعیت همگام‌سازی مشخص است.';}else{$endpoint=esc_url_raw(wp_unslash($_POST['endpoint']??''));$p=wp_parse_url($endpoint);if(($p['scheme']??'')!=='https'||substr($p['path']??'',-strlen('/integration_ingest.php'))!=='/integration_ingest.php'){$message='آدرس HTTPS دریافت دادهٔ پنل را وارد کنید.';}else{$token=trim(wp_unslash($_POST['token']??''));$read=trim(wp_unslash($_POST['read_token']??''));if(($token!==''&&!preg_match('/^[a-f0-9]{64}$/D',$token))||($read!==''&&strlen($read)<32)){$message='توکن معتبر نیست.';}else{$allowed=['products','inventory','sales','posts','pages'];$s['kinds']=array_values(array_intersect($allowed,(array)($_POST['kinds']??$allowed)));$s['allow_write']=!empty($_POST['allow_write']);$s['endpoint']=$endpoint;if($token!=='')$s['token']=$token;$s['read_token']=$read!==''?$read:($s['read_token']??wp_generate_password(48,false));update_option(self::OPTION,$s,false);$message='تنظیمات ذخیره شد؛ کلیدها دوباره نمایش داده نمی‌شوند.';}}}}
        $s=self::settings();echo '<div class="wrap"><h1>اتصال داده‌های مارکشو</h1><p>'.esc_html($message).'</p><p>در مرکز دادهٔ پروژه منبع وردپرس بسازید و توکن آن را اینجا وارد کنید. ارسال به سرور با HTTPS و حفظ بررسی گواهی انجام می‌شود.</p><form method="post">';wp_nonce_field('maarksho_bridge_save');echo '<fieldset><legend>نوع داده‌های مجاز توکن منبع</legend>';foreach(['products','inventory','sales','posts','pages'] as $kind)echo '<label style="margin-inline-end:14px"><input type="checkbox" name="kinds[]" value="'.esc_attr($kind).'" '.(in_array($kind,$s['kinds']??['products','inventory','sales','posts','pages'],true)?'checked':'').'>'.esc_html($kind).'</label>';echo '</fieldset>';echo '<p>آدرس دریافت پنل<br><input class="large-text" type="url" required name="endpoint" value="'.esc_attr($s['endpoint']??'').'" placeholder="https://maarksho.com/panel/integration_ingest.php"></p><p>توکن منبع پنل (خالی = حفظ قبلی)<br><input class="regular-text" type="password" name="token" autocomplete="new-password"></p><p>توکن خواندن REST برای پنل قدیمی (اختیاری، حداقل ۳۲ نویسه)<br><input class="regular-text" type="password" name="read_token" autocomplete="new-password"></p><p><label><input type="checkbox" name="allow_write" value="1" '.(!empty($s['allow_write'])?'checked':'').'> اجازهٔ به‌روزرسانی محصول/تصویر/قیمت از پنل قدیمی با توکن REST</label></p><button class="button button-primary">ذخیره</button></form><form method="post">';wp_nonce_field('maarksho_bridge_save');echo '<p><button class="button" name="run" value="1">پردازش یک بسته اکنون</button></p></form><h2>وضعیت</h2><p>WP-Cron هر ۵ دقیقه یک بسته را منتقل می‌کند. برای زمان‌بندی قابل اتکا Cron واقعی هاست را برای wp-cron.php فعال کنید. دریافت رسید هر بسته پیش از جابه‌جایی صفحه الزامی است.</p><pre>'.esc_html(wp_json_encode(get_option('maarksho_bridge_progress',[]),JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE)).'</pre></div>';
    }
    public static function permission($request){$s=self::settings();$header=$request->get_header('authorization');$token=strpos($header,'Bearer ')===0?substr($header,7):$request->get_header('x-maarksho-token');return !empty($s['read_token'])&&is_string($token)&&hash_equals($s['read_token'],$token);}
    public static function writePermission($request){$s=self::settings();return !empty($s['allow_write'])&&self::permission($request);}
    public static function routes(){foreach(['test','get-data','export'] as $path)register_rest_route('maarksho-crm/v1','/'.$path,['methods'=>'GET','permission_callback'=>[self::class,'permission'],'callback'=>[self::class,$path==='test'?'test':($path==='export'?'export':'legacy')]]);register_rest_route('maarksho-crm/v1','/update-product',['methods'=>'POST','permission_callback'=>[self::class,'writePermission'],'callback'=>[self::class,'updateProduct']]);}
    public static function test(){return ['status'=>'success','site_name'=>get_bloginfo('name'),'version'=>'5.0.0','woocommerce_active'=>function_exists('wc_get_products'),'capabilities'=>['products','inventory','sales','posts','pages','rank_math','yoast'],'pagination_required'=>true];}
    public static function seo($id){$rank=get_post_meta($id,'rank_math_title',true);$desc=get_post_meta($id,'rank_math_description',true);return ['seo_title'=>$rank?:get_post_meta($id,'_yoast_wpseo_title',true),'seo_description'=>$desc?:get_post_meta($id,'_yoast_wpseo_metadesc',true),'focus_keyword'=>get_post_meta($id,'rank_math_focus_keyword',true)?:get_post_meta($id,'_yoast_wpseo_focuskw',true),'canonical'=>get_post_meta($id,'rank_math_canonical_url',true)?:get_post_meta($id,'_yoast_wpseo_canonical',true),'robots'=>get_post_meta($id,'rank_math_robots',true)?:[],'seo_score'=>is_numeric(get_post_meta($id,'rank_math_seo_score',true))?(float)get_post_meta($id,'rank_math_seo_score',true):null];}
    public static function product($p){$attributes=[];foreach($p->get_attributes() as $name=>$attribute){if(is_object($attribute))$attributes[$name]=$attribute->is_taxonomy()?wc_get_product_terms($p->get_id(),$name,['fields'=>'names']):$attribute->get_options();else $attributes[$name]=(string)$attribute;}$id=$p->get_id();$imageIds=array_filter(array_merge([$p->get_image_id()],$p->get_gallery_image_ids()));return ['id'=>(string)$id,'name'=>$p->get_name(),'sku'=>$p->get_sku(),'url'=>get_permalink($id),'type'=>$p->get_type(),'parent_id'=>(string)$p->get_parent_id(),'status'=>$p->get_status(),'stock'=>$p->get_stock_quantity(),'price'=>$p->get_price()!==''?(float)$p->get_price():null,'currency'=>get_woocommerce_currency(),'description'=>wp_strip_all_tags($p->get_description()),'attributes'=>$attributes,'categories'=>wp_get_post_terms($p->get_parent_id()?:$id,'product_cat',['fields'=>'names']),'images'=>array_values(array_filter(array_map('wp_get_attachment_url',$imageIds))),'modified_at'=>$p->get_date_modified()?$p->get_date_modified()->date(DATE_ATOM):null]+self::seo($id);}
    public static function order($o){$gross=(float)$o->get_total();$refund=(float)$o->get_total_refunded();$date=$o->get_date_created();return ['id'=>(string)$o->get_id(),'date'=>$date?$date->date('Y-m-d'):gmdate('Y-m-d'),'status'=>$o->get_status(),'grain'=>'order','gross'=>$gross,'refund'=>$refund,'net'=>$gross-$refund,'orders'=>1,'currency'=>$o->get_currency(),'modified_at'=>$o->get_date_modified()?$o->get_date_modified()->date(DATE_ATOM):null];}
    public static function batch($kind,$page,$limit){
        if(in_array($kind,['products','inventory'],true)){
            if(!function_exists('wc_get_products'))return ['rows'=>[],'has_more'=>false,'unavailable'=>'WooCommerce inactive'];
            // Product variations have independent stock/SKU; WC data stores support HPOS-compatible product APIs.
            $query=new WP_Query(['post_type'=>['product','product_variation'],'post_status'=>['publish','private','draft','pending','trash'],'posts_per_page'=>$limit,'paged'=>$page,'orderby'=>'ID','order'=>'ASC','fields'=>'ids']);$rows=[];foreach($query->posts as $id){$p=wc_get_product($id);if($p)$rows[]=self::product($p);}return ['rows'=>$rows,'has_more'=>$page<$query->max_num_pages];
        }
        if($kind==='sales'){if(!function_exists('wc_get_orders'))return ['rows'=>[],'has_more'=>false,'unavailable'=>'WooCommerce inactive'];$orders=wc_get_orders(['limit'=>$limit,'page'=>$page,'paginate'=>true,'type'=>'shop_order','status'=>array_keys(wc_get_order_statuses()),'orderby'=>'ID','order'=>'ASC']);return ['rows'=>array_map([self::class,'order'],$orders->orders),'has_more'=>$page<$orders->max_num_pages];}
        if(!in_array($kind,['posts','pages'],true))return new WP_Error('invalid_kind','Unsupported kind',['status'=>400]);$q=new WP_Query(['post_type'=>$kind==='posts'?'post':'page','post_status'=>['publish','draft','private','pending','future','trash'],'posts_per_page'=>$limit,'paged'=>$page,'orderby'=>'ID','order'=>'ASC']);$rows=[];foreach($q->posts as $p){$id=$p->ID;$image=get_the_post_thumbnail_url($id,'full');$rows[]=['id'=>(string)$id,'title'=>get_the_title($id),'url'=>get_permalink($id),'status'=>$p->post_status,'description'=>wp_strip_all_tags($p->post_excerpt),'modified_at'=>get_post_modified_time(DATE_ATOM,true,$id),'images'=>$image?[$image]:[]]+self::seo($id);}return ['rows'=>$rows,'has_more'=>$page<$q->max_num_pages];
    }
    public static function export($request){$kind=$request->get_param('kind')?:'products';$page=max(1,(int)$request->get_param('page'));$limit=max(1,min(100,(int)($request->get_param('per_page')?:50)));$data=self::batch($kind,$page,$limit);if(is_wp_error($data))return $data;return ['status'=>'success','kind'=>$kind,'page'=>$page,'next_page'=>$data['has_more']?$page+1:null,'generated_at'=>gmdate(DATE_ATOM)]+$data;}
    public static function legacy($request){$p=self::batch('products',max(1,(int)$request->get_param('page')),50);$o=self::batch('sales',max(1,(int)$request->get_param('page')),50);return ['status'=>'success','products'=>$p['rows'],'orders'=>$o['rows'],'has_more'=>$p['has_more']||$o['has_more'],'warning'=>'Use /export and next_page for complete data.'];}
    public static function updateProduct($request){
        if(!function_exists('wc_get_product'))return new WP_Error('woocommerce_missing','WooCommerce inactive',['status'=>400]);
        $data=$request->get_json_params();$id=(int)($data['product_id']??0);$p=wc_get_product($id);if(!$p)return new WP_Error('not_found','Product not found',['status'=>404]);
        $args=['ID'=>$id];if(isset($data['title'])&&is_string($data['title']))$args['post_title']=sanitize_text_field($data['title']);if(isset($data['description'])&&is_string($data['description']))$args['post_content']=wp_kses_post($data['description']);
        if(isset($data['price'])&&(!is_scalar($data['price'])||!is_numeric($data['price'])||(float)$data['price']<0))return new WP_Error('price','Invalid price',['status'=>400]);
        $image=isset($data['image_url'])?esc_url_raw($data['image_url']):'';if($image!==''&&(!wp_http_validate_url($image)||wp_parse_url($image,PHP_URL_SCHEME)!=='https'))return new WP_Error('image','Public HTTPS image required',['status'=>400]);
        $updated=wp_update_post($args,true);if(is_wp_error($updated))return $updated;if(isset($data['price'])){$p->set_regular_price(wc_format_decimal($data['price']));$p->save();}
        foreach(['seo_title'=>['rank_math_title','_yoast_wpseo_title'],'seo_description'=>['rank_math_description','_yoast_wpseo_metadesc'],'seo_keyword'=>['rank_math_focus_keyword','_yoast_wpseo_focuskw']] as $field=>$metas)if(isset($data[$field])&&is_string($data[$field]))foreach($metas as $meta)update_post_meta($id,$meta,sanitize_text_field($data[$field]));
        $imageStatus='';if($image!==''){require_once ABSPATH.'wp-admin/includes/image.php';require_once ABSPATH.'wp-admin/includes/file.php';require_once ABSPATH.'wp-admin/includes/media.php';$attachment=media_sideload_image($image,$id,$args['post_title']??$p->get_name(),'id');if(is_wp_error($attachment))return new WP_Error('image_upload','Metadata saved, image download failed',['status'=>422]);set_post_thumbnail($id,$attachment);$imageStatus='Image uploaded';}
        return ['status'=>'success','product_id'=>$id,'updated'=>true,'image_status'=>$imageStatus];
    }
    public static function tick(){
        if(!add_option('maarksho_bridge_lock',time(),'','no')){$lock=(int)get_option('maarksho_bridge_lock');if($lock>time()-300)return;delete_option('maarksho_bridge_lock');if(!add_option('maarksho_bridge_lock',time(),'','no'))return;}
        try{$s=self::settings();if(empty($s['endpoint'])||empty($s['token']))return;$progress=get_option('maarksho_bridge_progress',['kind_index'=>0,'page'=>1,'cycle'=>wp_generate_uuid4()]);$kinds=$s['kinds']??['products','inventory','sales','posts','pages'];if(!$kinds)return;$progress['kind_index']=($progress['kind_index']??0)%count($kinds);$kind=$kinds[$progress['kind_index']];$page=max(1,(int)($progress['page']??1));$cycle=$progress['cycle']??wp_generate_uuid4();$data=self::batch($kind,$page,50);if(is_wp_error($data))return;
            if(!empty($data['unavailable'])){$progress['last_error']=$data['unavailable'];$progress['kind_index']=(($progress['kind_index']??0)+1)%count($kinds);$progress['page']=1;update_option('maarksho_bridge_progress',$progress,false);return;}
            $payload=['kind'=>$kind,'rows'=>$data['rows'],'batch_id'=>$cycle.'-'.$kind.'-'.$page.'-'.substr(hash('sha256',wp_json_encode($data['rows'])),0,12),'complete'=>!$data['has_more']];$response=wp_safe_remote_post($s['endpoint'],['timeout'=>20,'redirection'=>0,'sslverify'=>true,'headers'=>['Authorization'=>'Bearer '.$s['token'],'Content-Type'=>'application/json'],'body'=>wp_json_encode($payload)]);
            if(is_wp_error($response)){$progress['last_error']='NETWORK_ERROR';}elseif(wp_remote_retrieve_response_code($response)!==200){$progress['last_error']='PANEL_HTTP_'.wp_remote_retrieve_response_code($response);}else{$ack=json_decode(wp_remote_retrieve_body($response),true);if(!is_array($ack)||($ack['accepted']??null)!==count($data['rows'])){$progress['last_error']='INVALID_ACK';}else{$progress['last_error']=null;$progress['last_success']=gmdate(DATE_ATOM);$progress['last_kind']=$kind;$progress['last_page']=$page;if($data['has_more'])$progress['page']=$page+1;else{$progress['page']=1;$progress['kind_index']=(($progress['kind_index']??0)+1)%count($kinds);if($progress['kind_index']===0)$progress['cycle']=wp_generate_uuid4();}}}update_option('maarksho_bridge_progress',$progress,false);
        }finally{delete_option('maarksho_bridge_lock');}
    }
}
Maarksho_Data_Bridge::boot();register_activation_hook(__FILE__,[Maarksho_Data_Bridge::class,'activate']);register_deactivation_hook(__FILE__,[Maarksho_Data_Bridge::class,'deactivate']);
